type regionPlace struct {
	Name     string
	Lon, Lat float64
}

// regionGeo places a product region on the world map from the region
// catalog. A region that is not catalogued is drawn without a position.
func regionGeo(region string) (regionPlace, bool) {
	entry, ok := catalog.LookupName(region)
	return regionPlace{Name: entry.City, Lon: entry.Longitude, Lat: entry.Latitude}, ok
}

func ratioClass(value float64) string {
	switch {
	case value >= 0.9:
		return "bad"
	case value >= 0.75:
		return "warn"
	default:
		return "ok"
	}
}

// Name is the lower-case cell token used in NATS subjects and host descriptors.
func (e Entry) Name() string { return strings.ToLower(e.Cell) }

const (
	GRU = "GRU"
	SFO = "SFO"
	FRA = "FRA"
	// Bootstrap is the only cell that may found a deployment until a
	// separately reviewed migration exists.
	Bootstrap = GRU
)

// entries is ordered: placement assigns permanent members in this order.
var entries = [...]Entry{
	{Cell: GRU, OCIRegion: "sa-saopaulo-1", OCIRegionKey: "GRU", City: "São Paulo", Country: "BR", Latitude: -23.43, Longitude: -46.47},
	{Cell: SFO, OCIRegion: "us-sanjose-1", OCIRegionKey: "SJC", City: "San Jose", Country: "US", Latitude: 37.34, Longitude: -121.89},
	{Cell: FRA, OCIRegion: "eu-frankfurt-1", OCIRegionKey: "FRA", City: "Frankfurt", Country: "DE", Latitude: 50.11, Longitude: 8.68},

// LookupName returns the entry whose lower-case token is name.
func LookupName(name string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Name() == name {
			return entry, true
		}
	}
	return Entry{}, false
}

func (current view) capacityWarning(resources *regionview.ResourceView) string {
	for _, reading := range []*regionview.Reading{resources.MemoryBytes, resources.MemoryUsedBytes} {
		if reading != nil && !reading.Fresh(current.Now) {
			return "Capacity includes stale measurements; inspect the filesystem table for freshness."
		}
	}
	for _, filesystem := range resources.Filesystems {
		if filesystem.SizeBytes != nil && !filesystem.SizeBytes.Fresh(current.Now) || filesystem.UsedBytes != nil && !filesystem.UsedBytes.Fresh(current.Now) {
			return "Capacity includes stale measurements; inspect the filesystem table for freshness."
		}
	}
	return ""
}

func (current view) filesystemAvailable(filesystem regionview.Filesystem) string {
	if filesystem.SizeBytes == nil || filesystem.UsedBytes == nil || !filesystem.SizeBytes.ObservedAt.Equal(filesystem.UsedBytes.ObservedAt) {
		return "unavailable"
	}
	reading := regionview.Reading{Value: max(filesystem.SizeBytes.Value-filesystem.UsedBytes.Value, 0), ObservedAt: filesystem.SizeBytes.ObservedAt}
	return current.readingText(&reading, "bytes")
}
